<label class="form-label">Serial list format<select class="form-select mb-3" name="format" disabled><option value="csv">CSV: asset_tag,serial_number</option><option value="text">Plain text: one serial number per line</option></select></label></div>
<label class="form-label">Paste data<textarea class="form-control mb-3" name="content" data-import-content rows="12" placeholder="category,name,shop_quantity,unit,default_note,description&#10;FIXTURES,ETC Source 4,12,ea,,"></textarea></label>
